using System;using System.IO;using System.Linq;using System.Collections.Generic;
using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;
[InitializeOnLoad] public static class PatientFittedGownBuilder {
 const string Root="Assets/EmergencyPatientGown_Studio";const string Flag="Temp/PatientFittedGown.build";
 static PatientFittedGownBuilder(){EditorApplication.delayCall+=Run;}
 static float Width(float y){if(y<-.57f)return Mathf.Lerp(.125f,.225f,Mathf.InverseLerp(-.62f,-.57f,y));if(y<-.12f)return Mathf.Lerp(.225f,.19f,Mathf.InverseLerp(-.57f,-.12f,y));return Mathf.Lerp(.19f,.24f,Mathf.InverseLerp(-.12f,.48f,y));}
 static float Surface(float x,float y,Vector3[] body){float best=-1;float radius=.055f;foreach(var v in body){float dx=v.x*100-x,dy=v.y*100-y;if(Mathf.Abs(dx)<radius&&Mathf.Abs(dy)<radius){float dist=dx*dx+dy*dy;if(dist<radius*radius)best=Mathf.Max(best,v.z*100);}}if(best<0)best=.19f;float fold=.004f*Mathf.Sin(y*69+x*35)+.003f*Mathf.Sin(y*91-x*57)+.003f*Mathf.Cos(x*88);float smooth=.263f-.026f*Mathf.Pow(Mathf.Abs(x)/.26f,2)-.022f*Mathf.InverseLerp(-.1f,.5f,-y);return smooth+.005f*Mathf.Sin(x*34f+y*4f)*Mathf.Clamp01((.25f-y)/.7f);}
 static void Run(){if(!File.Exists(Flag))return;File.Delete(Flag);try{Build();File.WriteAllText("Temp/PatientFittedGown.done","PASS");}catch(Exception e){File.WriteAllText("Temp/PatientFittedGown.error",e.ToString());Debug.LogException(e);}}
 static void Build(){string original=SceneManager.GetActiveScene().path;var scene=SceneManager.GetActiveScene();var body=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<MeshFilter>(true)).First(x=>x.name=="Patient_Body");var mesh=LoadModeledMesh();string meshPath=Root+"/Patient_FittedGown.asset";var existingMesh=AssetDatabase.LoadAssetAtPath<Mesh>(meshPath);if(existingMesh)AssetDatabase.DeleteAsset(meshPath);AssetDatabase.CreateAsset(mesh,meshPath);
 var tex=AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"/CottonWeave.png");if(!tex)throw new Exception("Cotton texture missing");var mat=AssetDatabase.LoadAssetAtPath<Material>(Root+"/Patient_FittedGown.mat");if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(mat,Root+"/Patient_FittedGown.mat");}mat.SetTexture("_BaseMap",tex);mat.SetColor("_BaseColor",Color.white);mat.SetFloat("_Metallic",0);mat.SetFloat("_Smoothness",.16f);mat.SetTextureScale("_BaseMap",Vector2.one*3);mat.doubleSidedGI=true;mat.SetFloat("_Cull",0);EditorUtility.SetDirty(mat);
 foreach(var path in EmergencyLightingWorkbench.Scenes){var s=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);var b=s.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<MeshFilter>(true)).First(x=>x.name=="Patient_Body");var old=b.transform.parent.Find("Studio_Patient_Gown");if(old)old.gameObject.SetActive(false);var prior=b.transform.Find("Patient_FittedGown");if(prior)UnityEngine.Object.DestroyImmediate(prior.gameObject);var go=new GameObject("Patient_FittedGown");go.transform.SetParent(b.transform,false);go.AddComponent<MeshFilter>().sharedMesh=mesh;var rend=go.AddComponent<MeshRenderer>();rend.sharedMaterial=mat;rend.lightProbeUsage=LightProbeUsage.BlendProbes;rend.reflectionProbeUsage=ReflectionProbeUsage.BlendProbes;rend.shadowCastingMode=ShadowCastingMode.On;rend.receiveShadows=true;EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);}AssetDatabase.SaveAssets();EditorSceneManager.OpenScene(original,OpenSceneMode.Single);}
 [Serializable] class ModeledData { public Vector3[] vertices; public Vector2[] uvs; public int[] triangles; }
 static Mesh LoadModeledMesh(){var d=JsonUtility.FromJson<ModeledData>(File.ReadAllText(Root+"/BodyFittedGown.json"));if(d==null||d.vertices.Length<1000)throw new Exception("Modeled gown data missing");var m=new Mesh{name="Patient_BodyFittedGown"};m.indexFormat=IndexFormat.UInt32;m.vertices=d.vertices;m.uv=d.uvs;for(int i=0;i<d.triangles.Length;i+=3){int t=d.triangles[i+1];d.triangles[i+1]=d.triangles[i+2];d.triangles[i+2]=t;}m.triangles=d.triangles;m.RecalculateNormals();m.RecalculateBounds();return m;}
}
